from PIL import Image
p=np.load('source_pixels.npz')['rgb'].astype(float)
# list pixels with color thresholds in playfield each frame, connected components for white/red/blue
from scipy import ndimage
for typ in ['white','red','blue']:
  print('\\n',typ)
  for i in range(0,96,4):
    im=p[i,55:120,75:190]
    r,g,b=im[:,:,0],im[:,:,1],im[:,:,2]
    if typ=='white': m=(r>210)&(g>210)&(b>210)
    elif typ=='red': m=(r>120)&(r>g*1.6)&(r>b*1.6)
    else: m=(b>100)&(b>r*1.4)&(b>g*1.2)
    lab,n=ndimage.label(m)
    comps=[]
    for k in range(1,n+1):
      ys,xs=np.where(lab==k)
      if len(xs)>=2: comps.append((len(xs),round(xs.mean()+75,1),round(ys.mean()+55,1)))
    comps=sorted(comps,reverse=True)[:5]
    print(i,comps)
